create_shipping_profile.code:
use WebCommander\Resources\ShippingProfiles\ShippingProfiles;

$response = ShippingProfiles::createShippingProfile($client, [
    'shipping_profile' => [
        'name' => 'Metro profile',
        'description' => 'Metro deliveries',
        'rule_preference' => 'product_assigned_rule',
        'shipping_rules' => [31],
    ],
], transactionNo: 'TXN-IMPORT-0001');

echo $response->map['shipping_profile']['id'], PHP_EOL;

create_shipping_profile_wizard.code:
use WebCommander\Resources\ShippingProfiles\ShippingProfiles;

$response = ShippingProfiles::createShippingProfileWizard($client, [
    'shipping_profile' => [
        'name' => 'Wizard profile',
        'description' => 'Built in one call',
        'rule_preference' => 'product_assigned_rule',
        'shipping_rules' => [[
            'name' => 'Metro delivery',
            'description' => 'Metro deliveries',
            'shipping_class' => 2,
            'zones' => [['id' => 5], ['name' => 'Inner West']],
            'shipping_rate' => [
                'name' => 'Metro flat rate',
                'method' => 'flat_rate',
                'shipping_cost' => ['amount' => 10, 'type' => 'fixed'],
                'handling_cost' => ['amount' => 5, 'type' => 'percent'],
            ],
        ]],
    ],
]);

$profile = $response->map['shipping_profile'];
echo $profile['id'], ' ', $profile['name'], ' with ', $profile['rules_count'], ' rule(s)', PHP_EOL;

update_shipping_profile.code:
use WebCommander\Resources\ShippingProfiles\ShippingProfiles;

$response = ShippingProfiles::updateShippingProfile($client, 12, [
    'shipping_profile' => [
        'name' => 'Metro profile',
        'description' => 'Metro and inner west deliveries',
        'rule_preference' => 'lowest_shipping_cost_rule',
        'shipping_rules' => [31],
    ],
]);

echo $response->map['shipping_profile']['rule_preference'], PHP_EOL;
